import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c2_blocks.1.act_k8.npy')); b0=-6.4215
torch.manual_seed(5); N=8192
xi=torch.randn(N,2); c=torch.rand(N)
def run(fn=None, klo=0, khi=1):
    x=xi.clone(); lab=None
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,A=net.velocity(x,t,c,('blocks.1.act',),count=False)
        s=A['blocks.1.act']@w+b0
        if k==8: lab=(s>0).numpy()
        f=(s>0)&(klo<=k<khi)
        if fn is not None: v=torch.where(f[:,None],v+fn(x),v)
        x=x-v/20
    return x.numpy(), lab
a0,lab=run()
cn=c.numpy(); xn=xi.numpy()
ta=np.degrees(np.arctan2(xn[lab,1],xn[lab,0])); print('target noise angle pct',np.percentile(ta,[2,10,50,90,98]).round(0))
def hist(a,mask):
    ang=np.arctan2(a[:,1],a[:,0]); H,_,_=np.histogram2d(ang[mask],cn[mask],bins=[36,5],range=[[-np.pi,np.pi],[0,1]]); return H
ref=np.c_[a0,3*cn[:,None]]
def knnlab(a):
    q=np.c_[a,3*cn[:,None]]; out=[]
    for i in range(0,N,2048):
        d=((q[i:i+2048,None,:]-ref[None,::2,:])**2).sum(-1); idx=np.argsort(d,1)[:,:7]; out.append(lab[::2][idx].mean(1)>0.5)
    return np.concatenate(out)
Hk=hist(a0,~lab); Hk/=Hk.sum()
def ev(name,a):
    tl=knnlab(a); H=hist(a,~tl); H/=H.sum(); rr=np.linalg.norm(a,axis=1)
    print(name,'target',tl.mean().round(3),'TV',(0.5*np.abs(H-Hk).sum()).round(3),'offring',((rr<2.0)|(rr>3.9)).mean().round(4),flush=True)
def R(b): b=np.radians(b); return np.array([[np.cos(b),-np.sin(b)],[np.sin(b),np.cos(b)]])
for beta in [60,90,120,150,180,-60,-90,-120,-150]:
    M=torch.tensor(-20*(R(beta)-np.eye(2)),dtype=torch.float32)
    a,_=run(lambda x: x@M.T); ev(f'rot{beta}',a)

